  const fmtDate = s => { const d = new Date(s); return isNaN(d) ? "" : d.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }); };
  const readTime = w => { const m = w / 215; if (!(m > 0)) return ""; const h = Math.floor(m / 60), mm = Math.round(m % 60); return h > 0 ? h + "h" + mm + "m" : mm + "m"; };
