    const idm = link.match(/works\/(\d+)/) || link.match(/^\s*(\d{3,})\s*$/);
    if (!idm) { note("I need the AO3 link or the work number (the digits after /works/)."); return; }
    if (!title) { note("Give it a title so you can spot it in the list."); return; }
    const workId = idm[1];
    if (readJson(TRK_KEY, []).some(x => String(x.workId) === workId)) { note("That fic is already in your tracker."); return; }
    if (readJson(REM_KEY, []).some(x => String(x.workId) === workId)) { note("That fic is in your Removed list. Restore it from the Fic Tracker instead."); return; }
    const cm = fld.chapters.value.trim().match(/^(\d+)\s*(?:\/\s*(\d+|\?))?$/);
    if (fld.chapters.value.trim() && !cm) { note("Chapters should look like 14/23 or 5/?."); return; }
    const posted = cm ? Number(cm[1]) : 1;
    const label = cm ? posted + "/" + (cm[2] || "?") : null;
    const words = Number(String(fld.words.value).replace(/[^\d]/g, "")) || null;
    const readN = Math.min(Number(String(fld.read.value).replace(/[^\d]/g, "")) || 0, posted);
    const complete = !!(cm && cm[2] && cm[2] !== "?" && Number(cm[2]) === posted);
