    const sub = el("div", "font-family:'Courier New',Courier,monospace;font-size:10px;letter-spacing:0.04em;color:rgba(217,208,245,0.6);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;");
    ttl.appendChild(sub);
