          const line = el("div", "font-size:11.5px;line-height:1.35;color:rgba(233,228,245,0.85);padding:5px 8px;border-radius:7px;background:rgba(255,255,255,0.05);overflow-wrap:anywhere;");
          line.appendChild(el("span", "", `${nt.e} `));
