  popoutBtn.setAttribute("aria-label", "Open in new tab");
  popoutBtn.style.cssText = `font-size:11px;color:${P.accent};background:${P.btnBg};border:1px solid ${P.borderMid};border-radius:6px;cursor:pointer;padding:5px 9px;font-family:inherit;letter-spacing:0.02em;transition:background 0.15s,border-color 0.15s;display:flex;align-items:center;`;
  popoutBtn.onmouseover = () => { popoutBtn.style.background = P.btnHover; popoutBtn.style.borderColor = P.accentDim; };
  popoutBtn.onmouseout  = () => { popoutBtn.style.background = P.btnBg;    popoutBtn.style.borderColor = P.borderMid; };
  popoutBtn.onclick = () => openPopoutTab();

