  const READ_DAY_KEY = "ao3_read_today"; // { date: "YYYY-MM-DD", index: n }

  function getTodaysReadCard() {
    const todayStr = getPragueTodayIso();
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(READ_DAY_KEY) || "null"); } catch (e) { saved = null; }

    if (saved && saved.date === todayStr && Number.isInteger(saved.index) && READ_DECK[saved.index]) {
      return READ_DECK[saved.index];
    }

    const index = Math.floor(Math.random() * READ_DECK.length);
    localStorage.setItem(READ_DAY_KEY, JSON.stringify({ date: todayStr, index }));
    return READ_DECK[index];
  }

