  // ── "This month's progress" popup — the same bar/pace/daily-target rows
  // from the main dashboard's Statistics panel, recomputed standalone so it
  // can be reached by tapping the "words left today" line in the cycle
  // tracker without needing that panel open.
  function showMonthProgressPopup() {
    const existing = document.getElementById("ao3-monthprogress-popup");
    if (existing) existing.remove();
    const existingBackdrop = document.getElementById("ao3-monthprogress-backdrop");
    if (existingBackdrop) existingBackdrop.remove();

    const now = new Date();
    const monthRef = now;
    const lastDayOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();

    const dayRefCutoff = endOfDay(now);
    const monthWords = getLog()
      .filter(e => {
        const d = new Date(e.date);
        return isSameMonth(d, monthRef) && d <= dayRefCutoff;
      })
      .reduce((s, e) => s + e.words, 0);

    const lastMonthWords = getBestCompletedMonthWords(monthRef);
    const beatLastMonth  = lastMonthWords > MONTHLY_GOAL;
    const monthTarget = beatLastMonth ? lastMonthWords + 1 : MONTHLY_GOAL;
    const monthCap = monthTarget;

    const pct = Math.min(100, (monthWords / monthCap) * 100);
    const monthLabel = monthRef.toLocaleDateString(undefined, { month: "long", year: "numeric" });

    const backdrop = document.createElement("div");
    backdrop.id = "ao3-monthprogress-backdrop";
    backdrop.style.cssText = "position:fixed; inset:0; z-index:2147483000; background:rgba(0,0,0,0.4); perspective:800px;";

    const popup = document.createElement("div");
    popup.id = "ao3-monthprogress-popup";
    popup.style.cssText = `
      position:fixed; top:50%; left:50%; z-index:2147483001;
      transform:translate(-50%, -50%);
      animation: ao3TarotDropIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
      max-width:290px; width:calc(100% - 64px); max-height:78vh; overflow-y:auto;
      border-radius:18px; padding:22px 20px;
      background:linear-gradient(170deg, #241722, #14101a 65%, #1c1420);
      border:1.5px solid rgba(255,158,207,0.5);
      text-align:left; color:#ffeaf4;
    `;

    const badge = document.createElement("div");
    badge.textContent = "This month's progress";
    badge.style.cssText = "font-size:10px; font-weight:700; letter-spacing:0.08em; text-transform:uppercase; color:rgba(255,184,220,0.8); margin-bottom:14px; text-align:center;";
    popup.appendChild(badge);

    const barWrap = document.createElement("div");
    barWrap.style.cssText = `
      background:rgba(255,158,207,0.1); border-radius:999px;
      height:8px; overflow:hidden; margin-bottom:5px;
    `;
    const barFill = document.createElement("div");
    barFill.style.cssText = `
      height:100%; border-radius:999px; width:${pct.toFixed(1)}%;
      background:linear-gradient(90deg,#ff9ecf,#ffb8dc);
    `;
    barWrap.appendChild(barFill);
    popup.appendChild(barWrap);

    const barMetaDetail =
      formatReadingTime(monthWords) + " logged" +
      (beatLastMonth ? "  ·  goal: beat best month" : "");
    popup.appendChild(statRow(
      `${monthWords.toLocaleString()} / ${monthCap.toLocaleString()} words · ${pct.toFixed(0)}%`,
      barMetaDetail
    ));

    const elapsedFraction = Math.min(1, (now.getDate() - 1 + now.getHours() / 24) / lastDayOfMonth);
    const expectedWords   = monthCap * elapsedFraction;
    const paceDiff        = monthWords - expectedWords;
    const paceThreshold   = monthCap * 0.01;
    const paceDetail = `${pct.toFixed(0)}% done · ${(elapsedFraction * 100).toFixed(0)}% of month elapsed`;

    if (Math.abs(paceDiff) <= paceThreshold) {
      popup.appendChild(statRow("🎯 On track", paceDetail, "#a3be8c"));
    } else if (paceDiff > 0) {
      popup.appendChild(statRow(
        `🚀 Ahead by ${Math.round(paceDiff).toLocaleString()} words (${formatReadingTime(paceDiff)})`, paceDetail, "#a3be8c"
      ));
    } else {
      popup.appendChild(statRow(
        `⏳ Behind by ${Math.round(-paceDiff).toLocaleString()} words (${formatReadingTime(-paceDiff)})`, paceDetail, "#ffb8dc"
      ));
    }

    const wordsLeft = Math.max(0, monthTarget - monthWords);
    const daysLeft = lastDayOfMonth - now.getDate() + 1;
    if (wordsLeft > 0) {
      // Same start-of-day basis as the Statistics tab (today's words are already in monthWords)
      const todayWords = getLog()
        .filter(e => isSameDay(new Date(e.date), now))
        .reduce((s, e) => s + e.words, 0);
      const wordsLeftAtDayStart = Math.max(0, monthTarget - (monthWords - todayWords));
      const wordsPerDay = Math.ceil(wordsLeftAtDayStart / daysLeft);
      const goalLabel = beatLastMonth ? `beat best month` : `hit 700,000`;

      const expectedAtDayStart = monthCap * (now.getDate() - 1) / lastDayOfMonth;
      const steadyWordsLeft   = Math.max(0, monthTarget - expectedAtDayStart);
      const steadyWordsPerDay = Math.ceil(steadyWordsLeft / daysLeft);
      const paceAdjustment    = steadyWordsPerDay - wordsPerDay;
      const goalDetail =
        `${daysLeft} day${daysLeft !== 1 ? "s" : ""} left · ${formatReadingTime(wordsLeft)} total left` +
        (paceAdjustment > 0
          ? `  ·  ~${paceAdjustment.toLocaleString()} fewer/day (${formatReadingTime(paceAdjustment)}) thanks to your lead`
          : paceAdjustment < 0
            ? `  ·  ~${(-paceAdjustment).toLocaleString()} more/day (${formatReadingTime(-paceAdjustment)}) to make up your deficit`
            : "");

      popup.appendChild(statRow(
        `📖 ${wordsPerDay.toLocaleString()} words/day to ${goalLabel}`,
        goalDetail,
        "#ffb8dc"
      ));
    } else {
      const doneRow = document.createElement("div");
      doneRow.style.cssText = "font-size:12.5px; margin-bottom:7px; color:#a3be8c;";
      doneRow.textContent = beatLastMonth
        ? `✦ Best month beaten! (${lastMonthWords.toLocaleString()} words surpassed)`
        : `✦ Monthly goal of ${MONTHLY_GOAL.toLocaleString()} words reached!`;
      popup.appendChild(doneRow);
    }

    const closeHint = document.createElement("div");
    closeHint.textContent = "tap anywhere to close";
    closeHint.style.cssText = "margin-top:14px; font-size:10px; color:rgba(255,234,244,0.4); text-align:center;";
    popup.appendChild(closeHint);

    const close = () => { popup.remove(); backdrop.remove(); };
    backdrop.onclick = close;
    popup.onclick = close;

    document.body.appendChild(backdrop);
    document.body.appendChild(popup);
  }

