  // Pool → how many to show per "unroll" of the phase overview, and how they
  // get picked. Kept separate from the toggle state itself so re-renders
  // that happen for unrelated reasons (tapping some other stat while this
  // stays open) don't reshuffle mid-view — only actually opening it fresh does.
  const PHASE_OVERVIEW_PICK_COUNT = 3;
  let phaseOverviewPicks = null; // { phase, lines: [...] } | null

  function pickPhaseOverviewLines(phaseKey, pool) {
    if (!phaseOverviewPicks || phaseOverviewPicks.phase !== phaseKey) {
      const shuffled = [...pool];
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
      }
      phaseOverviewPicks = { phase: phaseKey, lines: shuffled.slice(0, Math.min(PHASE_OVERVIEW_PICK_COUNT, shuffled.length)) };
    }
    return phaseOverviewPicks.lines;
  }

  // the card, but does rotate day to day (same trick as the tarot/read draws).
  function pickDailyTip(pool, seedStr) {
    if (!pool || !pool.length) return null;
    let hash = 0;
    for (let i = 0; i < seedStr.length; i++) hash = (hash * 31 + seedStr.charCodeAt(i)) >>> 0;
    return pool[hash % pool.length];
  }

  const RESTOCK_ITEMS = [
    { icon: "🫧", label: "Boil cups" },
    { icon: "🩸", label: "Tampons" },
    { icon: "💊", label: "Pain relief" },
    { icon: "🔥", label: "Heating pads" },
    { icon: "🍫", label: "Comfort snacks" },
  ];
  const RESTOCK_KEY = "ao3_restock_check_v1"; // { anchor: "YYYY-MM-DD" (last period start), checked: [bool...] }

  // The checklist is keyed to the start date of the most recently logged
  // period. Once a new period gets logged, the anchor changes and the
  // checklist quietly resets — no manual "clear" step needed.
  function getRestockState(anchor) {
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(RESTOCK_KEY) || "null"); } catch (e) { saved = null; }
    if (!saved || saved.anchor !== anchor || !Array.isArray(saved.checked) || saved.checked.length !== RESTOCK_ITEMS.length) {
      saved = { anchor, checked: RESTOCK_ITEMS.map(() => false) };
      localStorage.setItem(RESTOCK_KEY, JSON.stringify(saved));
    }
    return saved;
  }
  function setRestockChecked(anchor, idx, value) {
    const state = getRestockState(anchor);
    state.checked[idx] = value;
    localStorage.setItem(RESTOCK_KEY, JSON.stringify(state));
  }

  // Small celebratory flourish for finishing the whole checklist — a brief
  // "you did it" banner plus a little emoji burst, both self-removing so
  // the popup doesn't stay cluttered afterward. Purely cosmetic; storage
  // stays exactly as it was.
  const CHECKLIST_CELEBRATE_EMOJI = ["🎉", "✨", "💗", "🌟"];
  function celebrateChecklistComplete(wrapEl, labelEl) {
    const existingBanner = wrapEl.parentElement && wrapEl.parentElement.querySelector(".ao3-checklist-done-banner");
    if (existingBanner) existingBanner.remove();

    const banner = document.createElement("div");
    banner.className = "ao3-checklist-done-banner";
    banner.textContent = "✨ all done — nice job taking care of yourself ✨";
    banner.style.cssText = `
      font-size:11.5px; font-weight:600; color:#8fd9c4; text-align:center;
      margin:2px 0 10px; animation: ao3ChecklistPop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) both;
    `;
    labelEl.insertAdjacentElement("afterend", banner);
    setTimeout(() => {
      banner.style.transition = "opacity 0.6s ease";
      banner.style.opacity = "0";
      setTimeout(() => banner.remove(), 650);
    }, 2200);

    for (let i = 0; i < 8; i++) {
      const emoji = document.createElement("div");
      emoji.textContent = CHECKLIST_CELEBRATE_EMOJI[Math.floor(Math.random() * CHECKLIST_CELEBRATE_EMOJI.length)];
      const dx = Math.round((Math.random() - 0.5) * 90);
      const rot = Math.round((Math.random() - 0.5) * 40);
      const size = 12 + Math.round(Math.random() * 6);
      emoji.style.cssText = `
        position:absolute; left:${10 + Math.random() * 80}%; top:${15 + Math.random() * 50}%;
        font-size:${size}px; pointer-events:none; --dx:${dx}px; --rot:${rot}deg;
        animation: ao3CompanionBurst ${0.75 + Math.random() * 0.5}s ease-out ${i * 0.05}s both;
      `;
      wrapEl.appendChild(emoji);
      setTimeout(() => emoji.remove(), 1700);
    }
  }

