  // Which question belongs to today -- picked with the same seeded-random
  // pattern as the daily mood/trinket, so it's fixed for the day but not a
  // visible rotation from one day to the next. Always returns one now that
  // check-ins happen every day.
  function getDailyCheckin(dayIndex) {
    const idx = Math.floor(seededDailyRandom(dayIndex + 9500) * COMPANION_CHECKINS.length);
    return { ...COMPANION_CHECKINS[idx], questionId: idx };
  }

  // Returns today's answer if one was already given, else null.
  function getTodaysCheckin() {
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(CHECKIN_DAY_KEY) || "null"); } catch (e) { saved = null; }
    const todayStr = getPragueTodayIso();
    if (saved && saved.date === todayStr && Number.isInteger(saved.questionId) && Number.isInteger(saved.optionIndex)
        && COMPANION_CHECKINS[saved.questionId] && COMPANION_CHECKINS[saved.questionId].options[saved.optionIndex]) {
      return saved;
    }
    return null;
  }

  function getCheckinLog() {
    try {
      const log = JSON.parse(localStorage.getItem(CHECKIN_LOG_KEY) || "[]");
      return Array.isArray(log) ? log : [];
    } catch { return []; }
  }
  function saveCheckinLog(log) { localStorage.setItem(CHECKIN_LOG_KEY, JSON.stringify(log)); }

  // Answers today's check-in, but only the first answer counts -- a second
  // tap just returns the same saved answer instead of letting you re-roll.
  function answerCheckin(questionId, optionIndex) {
    const existing = getTodaysCheckin();
    if (existing) return existing;
    const saved = { date: getPragueTodayIso(), questionId, optionIndex };
    localStorage.setItem(CHECKIN_DAY_KEY, JSON.stringify(saved));
    const log = getCheckinLog();
    if (!log.some(e => e.date === saved.date)) {
      log.push(saved);
      saveCheckinLog(log);
    }
    return saved;
  }

  function showCheckinPopup(checkin, phaseColor) {
    const existingPopup = document.getElementById("ao3-checkin-popup");
    if (existingPopup) existingPopup.remove();
    const existingBackdrop = document.getElementById("ao3-checkin-backdrop");
    if (existingBackdrop) existingBackdrop.remove();

    const backdrop = document.createElement("div");
    backdrop.id = "ao3-checkin-backdrop";
    backdrop.style.cssText = "position:fixed; inset:0; z-index:2147483000; background:rgba(0,0,0,0.4); perspective:800px;";

    const popup = document.createElement("div");
    popup.id = "ao3-checkin-popup";
    popup.style.cssText = `
      position:fixed; top:50%; left:50%; z-index:2147483001;
      transform:translate(-50%, -50%);
      animation: ao3TarotDropIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
      max-width:280px; width:calc(100% - 64px); max-height:78vh; overflow-y:auto;
      border-radius:18px; padding:22px 20px;
      background:linear-gradient(170deg, #2a1c26, #14101a 65%, #1c1420);
      border:1.5px solid ${hexToRgba(phaseColor, 0.55)};
      text-align:center; color:#ffeaf4;
    `;

    const close = () => { popup.remove(); backdrop.remove(); };
    backdrop.onclick = close;

    const badge = document.createElement("div");
    badge.textContent = "✦ your companion asks ✦";
    badge.style.cssText = "font-size:10px; font-weight:600; letter-spacing:0.08em; text-transform:uppercase; color:rgba(255,184,220,0.7); margin-bottom:14px;";
    popup.appendChild(badge);

    const renderBody = () => {
      while (popup.childNodes.length > 1) popup.removeChild(popup.lastChild);

      const already = getTodaysCheckin();
      if (already) {
        const option = COMPANION_CHECKINS[already.questionId].options[already.optionIndex];

        const questionEl = document.createElement("div");
        questionEl.textContent = COMPANION_CHECKINS[already.questionId].question;
        questionEl.style.cssText = "font-size:13px; font-weight:600; color:#ffeaf4; margin-bottom:8px;";
        popup.appendChild(questionEl);

        const answerEl = document.createElement("div");
        answerEl.textContent = `You said: "${option.label}"`;
        answerEl.style.cssText = "font-size:11px; color:rgba(255,234,244,0.55); margin-bottom:10px;";
        popup.appendChild(answerEl);

        const divider = document.createElement("div");
        divider.style.cssText = `height:1px; background:${hexToRgba(phaseColor, 0.25)}; margin:0 auto 12px; width:60%;`;
        popup.appendChild(divider);

        const reactionText = document.createElement("div");
        reactionText.textContent = `Your companion ${option.reaction}`;
        reactionText.style.cssText = "font-size:13px; line-height:1.5; font-weight:500; color:#ffeaf4; margin-bottom:14px;";
        popup.appendChild(reactionText);

        const note = document.createElement("div");
        note.style.cssText = "font-size:10px; color:rgba(255,234,244,0.4);";
        note.textContent = "it'll ask something new another day.";
        popup.appendChild(note);
      } else {
        const questionEl = document.createElement("div");
        questionEl.textContent = checkin.question;
        questionEl.style.cssText = "font-size:14px; font-weight:600; color:#ffeaf4; margin-bottom:16px;";
        popup.appendChild(questionEl);

        const optionsCol = document.createElement("div");
        optionsCol.style.cssText = "display:flex; flex-direction:column; gap:8px;";
        checkin.options.forEach((option, idx) => {
          const btn = document.createElement("button");
          btn.type = "button";
          btn.textContent = option.label;
          btn.style.cssText = `
            font-size:12.5px; font-weight:600; padding:9px 12px; border-radius:10px; cursor:pointer;
            background:${hexToRgba(phaseColor, 0.1)}; border:1px solid ${hexToRgba(phaseColor, 0.35)};
            color:#ffeaf4; transition:transform 0.15s, background 0.15s;
          `;
          btn.onmouseover = () => { btn.style.background = hexToRgba(phaseColor, 0.22); btn.style.transform = "scale(1.02)"; };
          btn.onmouseout  = () => { btn.style.background = hexToRgba(phaseColor, 0.1); btn.style.transform = "scale(1)"; };
          btn.onclick = () => { answerCheckin(checkin.questionId, idx); renderBody(); };
          optionsCol.appendChild(btn);
        });
        popup.appendChild(optionsCol);
      }

      const closeHint = document.createElement("div");
      closeHint.textContent = "tap outside to close";
      closeHint.style.cssText = "margin-top:16px; font-size:10px; color:rgba(255,234,244,0.4);";
      popup.appendChild(closeHint);
    };

    renderBody();

    document.body.appendChild(backdrop);
    document.body.appendChild(popup);
  }


